import{_ as t,o,c as r,a2 as d}from"./chunks/framework.DqYch1Cg.js";const h=JSON.parse('{"title":"Docker 与部署边界","description":"","frontmatter":{},"headers":[],"relativePath":"概念与原理/20deploy/s_deploy_6-docker.md","filePath":"概念与原理/20deploy/s_deploy_6-docker.md","lastUpdated":1794211306000}'),a={name:"概念与原理/20deploy/s_deploy_6-docker.md"};function s(c,e,l,p,n,i){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="docker-与部署边界" tabindex="-1">Docker 与部署边界 <a class="header-anchor" href="#docker-与部署边界" aria-label="Permalink to &quot;Docker 与部署边界&quot;">​</a></h1><h2 id="镜像、容器、网络与卷" tabindex="-1">镜像、容器、网络与卷 <a class="header-anchor" href="#镜像、容器、网络与卷" aria-label="Permalink to &quot;镜像、容器、网络与卷&quot;">​</a></h2><p>镜像是应用运行所需文件和元数据的只读模板，容器是镜像的运行实例；容器共享宿主机内核，不等于完整虚拟机。端口映射决定外部入口，容器中的 <code>localhost</code> 只代表该容器自身。数据库容器可以通过服务名互联，不应为了方便把数据库端口直接暴露到公网。</p><p>可写层随容器删除可能消失；数据库数据需要持久卷和独立备份。卷解决持久化，不能替代备份，也不能直接把运行中数据库目录的文件复制当成一致性备份。</p><h2 id="设计一份镜像时检查什么" tabindex="-1">设计一份镜像时检查什么？ <a class="header-anchor" href="#设计一份镜像时检查什么" aria-label="Permalink to &quot;设计一份镜像时检查什么？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层面</th><th>学习重点</th></tr></thead><tbody><tr><td>构建</td><td>多阶段构建，构建依赖与运行依赖分开，锁文件保证可重复安装</td></tr><tr><td>内容</td><td><code>.dockerignore</code> 排除本地缓存、Git 目录、环境文件和密钥</td></tr><tr><td>运行</td><td>非 root 用户、明确工作目录和资源限制</td></tr><tr><td>启动</td><td>exec 形式如 <code>CMD [&quot;node&quot;, &quot;dist/main.js&quot;]</code>，让进程接收退出信号</td></tr><tr><td>版本</td><td>固定可追踪版本；对可变 tag 的更新有策略，必要时固定 digest</td></tr><tr><td>配置</td><td>运行时注入配置，不能将密钥写入镜像层或构建日志</td></tr><tr><td>退出</td><td>排空与清理时间应小于平台终止窗口</td></tr></tbody></table><p>Node 作为容器主进程还要考虑子进程回收；存在多进程需求时评估 init 进程，而不是习惯性加 PM2。容器健康检查能报告状态，具体是否重启、摘流由运行平台决定。</p><h2 id="compose-不等于生产治理" tabindex="-1">Compose 不等于生产治理 <a class="header-anchor" href="#compose-不等于生产治理" aria-label="Permalink to &quot;Compose 不等于生产治理&quot;">​</a></h2><p>Compose 适合描述本地 API + PostgreSQL 等服务依赖。容器启动顺序不代表数据库已经可接入；即使有健康条件，应用也需要有限重试和故障恢复。数据库迁移建议作为受控的一次性发布步骤，不让所有副本同时抢着执行。</p><p>镜像回滚与数据库回滚仍是两件事。先学习单机部署与故障恢复，再根据负载和团队能力引入编排平台。</p><p>关联阅读：<a href="./s_deploy_4-node_process">Node 进程与停机</a>、<a href="./s_deploy_5-release">发布与回滚</a>、<a href="/FE-prepare-interview/概念与原理/18nestjs/s_nestjs_10-fullstack">NestJS 全栈实践</a>。本节补充旧笔记缺少的容器边界，不代表已给本项目增加 Docker 部署。</p><blockquote><p>来源：<a href="https://docs.docker.com/get-started/docker-concepts/" target="_blank" rel="noreferrer">Docker 概念文档</a>；<a href="https://docs.docker.com/build/building/best-practices/" target="_blank" rel="noreferrer">构建最佳实践</a>；个人部署笔记的容器化补充整理。</p></blockquote>',12)])])}const k=t(a,[["render",s]]);export{h as __pageData,k as default};
